const PROXY_URL = "http://localhost:4000/api/weather"; // 프록시 서버 주소

// 기상청 단기/초단기예보에 맞는 base_date, base_time 생성 함수
function getBaseDateTime() {
  const now = new Date();
  let baseDate = now.toISOString().slice(0, 10).replace(/-/g, ""); // YYYYMMDD
  let baseTime = "";

  // 예보 발표 시간 (기상청 가이드 참고, 02시부터 3시간 간격)
  const forecastTimes = [2, 5, 8, 11, 14, 17, 20, 23];
  let hour = now.getHours();
  let findTime = forecastTimes[0];

  for (let i = 0; i < forecastTimes.length; i++) {
    if (hour >= forecastTimes[i]) findTime = forecastTimes[i];
  }
  baseTime = String(findTime).padStart(2, "0") + "00";

  return { baseDate, baseTime };
}

// 실제 API 요청 함수
export async function fetchWeatherData(nx = 68, ny = 107) {
  const { baseDate, baseTime } = getBaseDateTime();

  // 원하는 카테고리: T1H(기온), REH(습도), SKY(하늘상태), PTY(강수형태), WSD(풍속)
  const params = new URLSearchParams({
    base_date: baseDate,
    base_time: baseTime,
    nx,
    ny
  });

  // 프록시 서버에 요청 (프록시 서버는 이 파라미터로 기상청 API를 호출해야 함)
  const url = `${PROXY_URL}?${params.toString()}`;

  try {
    const res = await fetch(url);
    if (!res.ok) throw new Error("서버 응답 오류");
    const data = await res.json();
    console.log("프론트에서 받은 응답:", data);
    return data;
  } catch (err) {
    console.error("날씨 정보 요청 실패:", err);
    throw err;
  }
}
